rows = []
source_text = (DOCS / '_run/edges.md').read_text(encoding='utf-8-sig')
for line in source_text.splitlines():
    if re.match(r'^\| E-\d+ \|', line):
        cells = [x.strip() for x in line.strip().strip('|').split('|')]
        assert len(cells) == 5, cells
        rows.append(dict(zip(('id', 'scene', 'trigger', 'expect', 'owner'), cells)))
assert len(rows) == len(TRANSLATIONS) == 104
for row, translation in zip(rows, TRANSLATIONS):
    fields = translation.split('|||')
    assert len(fields) == 3, (row['id'], fields)
    assert not re.search(r'[\u3400-\u9fff]', translation)
    stem = f"{int(row['id'][2:]):02d}"
    state = {'edge': dict(zip(('scene', 'trigger', 'expect'), fields)), 'modules': MODULES}
    (ROOT / f'{stem}.state.json').write_text(json.dumps(state, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
(ROOT / 'source-edges.md').write_text(source_text, encoding='utf-8')
(ROOT / 'source-06.md').write_text((DOCS / '02-设计/06-系统架构与模块划分.md').read_text(encoding='utf-8-sig'), encoding='utf-8')
(ROOT / 'source-rows.json').write_text(json.dumps(rows, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'states': len(rows), 'modules_chars': sum(map(len, MODULES.values())), 'output': str(ROOT)}, ensure_ascii=False))
